import{_ as t,h as s,i as e,c as r,v as l,p as o,x as n,m as p,e as c,S as d}from"./chunks/framework.Dvtg8yj2.js";const m=JSON.parse('{"title":"铜缆 Spine 短距 vs 光模块长距","description":"","frontmatter":{"title":"铜缆 Spine 短距 vs 光模块长距","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/copper-spine-vs-optics.md","filePath":"llm/copper-spine-vs-optics.md","lastUpdated":1788454257000}'),A={name:"llm/copper-spine-vs-optics.md"};function P(h,a,E,B,u,N){const i=s("Mermaid");return e(),r("div",null,[a[1]||(a[1]=l('<h1 id="铜缆-spine-短距-vs-光模块长距" tabindex="-1">铜缆 Spine 短距 vs 光模块长距 <a class="header-anchor" href="#铜缆-spine-短距-vs-光模块长距" aria-label="Permalink to &quot;铜缆 Spine 短距 vs 光模块长距&quot;">​</a></h1><div class="epigraph"><p>短距用铜，是因为电信号在机柜尺度上仍能扛住带宽与功耗；长距用光，是因为光纤的到达距离与布线密度是铜缆给不起的。</p><footer>—— 对照 NVIDIA 对 NVL72 机柜级 NVLink（短距铜互连）与柜外 InfiniBand / 以太网（可插拔光模块）的公开分层</footer></div><p>超节点把 GPU 之间最密的那张图收进机柜之后，物理层必须选介质。NVIDIA 公开的 GB200 / GB300 NVL72 用 NVLink Switch 在柜内做 GPU 全互连，这一层是短距电互连（铜缆 / 背板组件），而不是把 72 张卡两两插上可插拔光模块；柜与柜之间走 Quantum InfiniBand 或 Spectrum-X 以太网，这一层在数据中心距离上普遍落成光模块加光纤。两层都可以叫「高带宽」，但延迟、功耗、可维护性、故障单元不是同一件事。本篇只讨论这一分层为什么成立，以及它对集合通信与机房布线的约束。不编造未出现在厂商文档里的铜缆单通道速率、光模块瓦数或未发布的 CPO 量产带宽。</p><p><a href="/llm/gb200-nvl72">NVL72 超节点</a> 写产品封装；<a href="/llm/all-to-all-vs-clos">机内全互连与 Clos</a> 写拓扑。这里只写介质。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>GPU 间要搬的字节，训练时是激活与梯度，推理 decode 时是小消息的 All-Reduce / All-to-All。介质一旦选错，同样的 NCCL 调用会从「可被计算掩盖」变成「步步等网」。铜缆在短距上功耗低、延迟低、不需要激光与 PAM 光 DSP；但到达距离按米计，过了机柜、过了排，眼图与重量都会先投降。光模块把电信号变成光，光纤轻、可走几十米到机房跨排，却引入模块功耗、光口故障、以及一次额外的电–光–电。</p><p>若柜内也用可插拔光模块去堆 72 卡全互连，端口数、功耗与盲插维护会压过密度目标——NVL72 本来就是靠液冷把计算和交换托盘塞进同一柜。若柜间仍坚持铜缆，线束重量与长度会限制 Scale-Out 的布线半径。问题不是「光比铜先进」，而是：<strong>哪一段距离配哪一种物理层</strong>。把营销里的「光互连」或「铜互连」当成整张集群的单一答案，会在错误的 hop 上付错误的电。</p><h3 id="两段距离、两种故障单元" tabindex="-1">两段距离、两种故障单元 <a class="header-anchor" href="#两段距离、两种故障单元" aria-label="Permalink to &quot;两段距离、两种故障单元&quot;">​</a></h3><p>机柜内：计算托盘到交换托盘的路径长度是机柜尺度。NVIDIA 把这一层做成 NVLink Switch System，产品页给出域内 130 TB/s 的 GPU 通信聚合、每 GPU 1.8 TB/s 的第五代 NVLink。公开硬件叙事是托盘经背板 / 铜缆组件上到交换托盘。故障单元是托盘、背板、交换芯片——坏一块，影响的是超节点域，而不是一根独立的可热插光模块链路。</p><p>机柜外：超节点之间、超节点到存储，距离是列、排、机房。GB300 产品页写 ConnectX-8 为每 GPU 提供 800 Gb/s 的网络连接，可走 InfiniBand 或以太网。这一层的可插拔光模块（OSFP / QSFP 一类）是可现场更换的故障单元：坏一只模块，掉的是一条 Scale-Out 轨，不必重启整柜 NVLink 域。延迟与有效带宽按数据中心 hop 计，和域内 NVLink 不在同一档。</p><p><span class="marginnote">「铜」在这里指短距电互连，包括背板印制线与铜缆组件，不特指某一种连接器型号。未在官方材料点名的连接器机械尺寸、单 lane 波特率，本文不补。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>规划时把流量先分类。层内、步内、与激活同量级的集合通信，必须假设走柜内铜脊：TP 的 All-Reduce、域内 EP 的 All-to-All、超节点内 PD 分离的 KV 搬运。副本梯度、检查点、跨超节点的流水线，走柜外光口。分类错一次，NCCL 仍会调用成功，只是 busbw 掉到网卡档。</p>',13)),(e(),o(d,null,{default:n(()=>[c(i,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20RACK%5B%22%E6%9C%BA%E6%9F%9C%20%2F%20%E8%B6%85%E8%8A%82%E7%82%B9%22%5D%0A%20%20%20%20GPU%5B%22GPU%22%5D%0A%20%20%20%20SW%5B%22NVLink%20Switch%22%5D%0A%20%20%20%20GPU%20---%20%7C%22%E7%9F%AD%E8%B7%9D%E9%93%9C%E8%84%8A%22%7C%20SW%0A%20%20end%0A%20%20subgraph%20DC%5B%22%E6%95%B0%E6%8D%AE%E4%B8%AD%E5%BF%83%E7%BD%91%E7%BB%9C%22%5D%0A%20%20%20%20LEAF%5B%22%E5%8F%B6%E5%AD%90%20%2F%20%E8%84%8A%E6%9F%B1%E4%BA%A4%E6%8D%A2%E6%9C%BA%22%5D%0A%20%20%20%20OPT%5B%22%E5%85%89%E6%A8%A1%E5%9D%97%20%2B%20%E5%85%89%E7%BA%A4%22%5D%0A%20%20%20%20LEAF%20---%20OPT%0A%20%20end%0A%20%20RACK%20--%3E%7C%22800%20Gb%2Fs%20%E9%87%8F%E7%BA%A7%E7%BD%91%E5%8D%A1%22%7C%20OPT%0A%20%20TP%5B%22TP%20%2F%20%E5%9F%9F%E5%86%85%20EP%22%5D%20--%3E%20RACK%0A%20%20DP%5B%22DP%20%2F%20%E5%AD%98%E5%82%A8%20%2F%20%E8%B7%A8%E6%9F%9C%22%5D%20--%3E%20DC%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<p>运维上也按介质分工。铜脊侧：液冷、背板、交换托盘固件是柜级维护，窗口按超节点设计。光口侧：备件是模块与光纤，可以按端口替换；要为光衰、极性、多模 / 单模类型留验收，而不是把 NVLink 的「插上就有域」预期搬到机房跳线。功耗账分开算：柜内铜脊的电已经打进超节点 TDP 与液冷；柜外光模块的电打进网卡与交换机，随 Scale-Out 端口数线性涨。不要用「机柜已经液冷」当借口忽略光模块的机房功率。</p><h3 id="为何不把光模块塞进柜内全互连" tabindex="-1">为何不把光模块塞进柜内全互连 <a class="header-anchor" href="#为何不把光模块塞进柜内全互连" aria-label="Permalink to &quot;为何不把光模块塞进柜内全互连&quot;">​</a></h3><p>全互连的端口数随 GPU 数增长。72 张卡若每张再引出可插拔光口去做 GPU–GPU，面板、线束与模块故障率会成为密度的一阶项。NVLink Switch 把交叉收进交换托盘，计算托盘只连到柜内脊，物理层就可以用短距电信号喂饱官方给出的每 GPU 1.8 TB/s。光的优势——到达距离——在机柜内部用不上；光的代价——光电转换与可插拔件——却会逐端口付。这是短距选铜的工程原因，不是「铜的比特率永远更高」。</p><p>柜外相反。800 Gb/s 量级的 SuperNIC 要连到叶子交换机，线长按机房走。光纤的重量、弯曲半径与抗干扰，在这一距离上压过铜缆。可插拔模块让同一套网卡可以按机房标准换代（速率、单模 / 多模），而不改 GPU 底板。Scale-Out 本来就要面对 Clos 的分层与拥塞，介质选光是为了把距离问题从「传不达」变成「交换机怎么排队」，见下一篇拓扑。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>电信号在铜上的损耗随频率与长度上升。机柜尺度上，NVLink 这类专用 SerDes 仍能以公开规格运行：第五代相对 PCIe Gen5，NVIDIA 技术博客写过每 GPU 1.8 TB/s、约为 PCIe Gen5 的 14 倍。这组数字描述的是<strong>已封装好的短距链路</strong>，不是随手延长到邻柜仍能保持的速率。把同样的电信号拉到数十米，不是软件调 NCCL 能解决的，而是眼图与功耗先越界。</p><p>光模块把高速电变成光，光纤损耗远低于铜。换来的是：激光 / 硅光、DSP、时钟恢复、以及模块与交换机的协议栈。这些是数据中心网络的常规税，InfiniBand 与以太网都付。税的回报是可达性与热插拔。超节点架构把「付税」限制在柜外，让柜内集合通信不必每跳都做一次光电转换。</p><p><span class="marginnote">未来若把共封装光学（CPO）做到交换芯片边上，改变的是光口的封装位置与功耗曲线，不是「柜内可以不要交换」。在厂商未把某一代 NVLink 的公开规格写成光脊之前，不要把路线图当现网带宽。</span></p><h3 id="对延迟敏感通信的含义" tabindex="-1">对延迟敏感通信的含义 <a class="header-anchor" href="#对延迟敏感通信的含义" aria-label="Permalink to &quot;对延迟敏感通信的含义&quot;">​</a></h3><p>Decode 一步的集合通信消息小、发起频繁，对延迟的一阶导数大。铜脊上的 NVLink 跳数少、没有光 DSP 流水线，适合这一工作点。Prefill 大 GEMM 或数据并行的大梯度，体积大、可重叠，更能容忍柜外光口的延迟。因此介质分层与并行维分层是同一张表：<a href="/llm/tensor-parallel">张量并行</a> 不要跨光口；数据并行可以。混合精度与量化不改变这张表——它们减字节，但不把光口变成 NVLink。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要写「铜缆 X Gb/s / lane」除非它印在你引用的那份 NVIDIA 规格上。不要把某款 800 Gb/s 光模块的厂商典型功耗抄成 NVL72 的柜内预算。不要假设所有 Scale-Out 端口都是光：机柜内短跳线、DAC 在以太网里同样存在，只是 NVL72 的 GPU 全互连叙事是 NVLink 铜脊，柜外产品页给的是 SuperNIC 速率，不是某一只模块的 BOM。</p><p>也不要把「短距铜、长距光」理解成永远的物理定律。距离、波特率、封装演进都会移动分界。本文的分界是这一代公开产品：超节点域内走 NVLink 短距电互连，超节点之间走数据中心网络。昇腾或其他厂商的超节点若用不同介质，以他们的文档为准，不能把 NVL72 的铜脊抄过去当通用背板。</p><p><span class="marginnote">出处：NVIDIA GB200 / GB300 NVL72 产品页中的 NVLink 域与 ConnectX-8 速率、GB200 技术博客中相对 PCIe Gen5 的 NVLink 对照。不引用未公开的铜缆测试报告。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>柜内 GPU 全互连是短距电互连（铜脊 / 背板），用来喂饱已公布的每 GPU 1.8 TB/s NVLink 与 130 TB/s 域聚合。</li><li>柜外 Scale-Out 走 InfiniBand / 以太网；GB300 产品页给出每 GPU 800 Gb/s 量级的 SuperNIC，长距普遍落成光模块。</li><li>选介质的判据是距离、功耗、故障单元与是否要热插拔，不是「光比铜更 AI」。</li><li>TP 与域内 EP 不要跨到光口；DP、存储、跨超节点流量走光口。</li><li>不要编造单通道铜缆或光模块瓦数；规划用官方域规格加自己的 NCCL / 网卡微基准。</li><li>拓扑上的全互连与 Clos 分层见 <a href="/llm/all-to-all-vs-clos">机内全互连 vs 分层 Clos</a>。</li></ul>',16))])}const D=t(A,[["render",P]]);export{m as __pageData,D as default};
